mapper.select:
SELECT prompt_id, prompt_type, scene_prompt
FROM bt_bot_scene_prompt
WHERE status_cd = '00A'
  AND scene_id = #{sceneId}
  AND tenant_id = #{tenantId}

SELECT skill_type, skill_id, ext_skill_id, skill_name, skill_config_json, skill_json, CASE WHEN skill_json IS NOT NULL AND skill_json LIKE '%"tenantId":"-1"%' THEN 1 END AS platform
FROM bt_bot_scene_skill
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND scene_id = #{sceneId}

SELECT skill_id
FROM bt_bot_scene_skill
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND scene_id = #{sceneId}
  AND skill_type = 'knowledgeChat'

SELECT skill_id, skill_json, ext_skill_id
FROM bt_bot_scene_skill
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND scene_id = #{sceneId}
  AND skill_type = 'knowledgeChat'

SELECT scene_graph_json
FROM bt_bot_scene
WHERE tenant_id = #{tenantId}
  AND scene_id = #{sceneId}

SELECT scene_type, model_id, model_config_json
FROM bt_bot_scene
WHERE status_cd = '00A'
  AND scene_id = #{sceneId}
  AND tenant_id = #{tenantId}

SELECT scene_name AS name, CASE WHEN scene_type = 'chatflow' THEN 1 ELSE 0 END AS chatflow, scene_dsl AS dsl_json
FROM bt_bot_scene
WHERE status_cd = '00A'
  AND scene_id = #{sceneId}
  AND tenant_id = #{tenantId}


SELECT scene_id, scene_type, scene_icon
FROM bt_bot_scene
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND scene_id = #{sceneId}

SELECT scene_name
FROM bt_bot_scene
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND scene_id = #{sceneId}

SELECT file_name, file_content
FROM bt_claw_workspace
WHERE status_cd = '00A'
  AND scene_id = #{sceneId}
  AND tenant_id = #{tenantId}
  AND file_name IN (#{name})

SELECT a.id, b.variable_code, c.variable_val
FROM bt_claw_env_variable a
LEFT JOIN bt_env_variable b ON a.variable_id = b.variable_id AND a.tenant_id = b.tenant_id
LEFT JOIN bt_env_variable_val c ON b.variable_id = c.variable_id AND b.tenant_id = c.tenant_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.scene_id = #{sceneId}
  AND c.env_code = #{envCode}
